referenceSolutions.python:
def expandingPanelsBossReceipt(readings, k):
    a=readings
    out=[]
    left=0
    s=0
    for right,x in enumerate(a):
        s+=x
        while left<=right and s-a[left]>=k:
            s-=a[left]
            left+=1
        out.append(right-left+1 if s>=k else 0)
    return sum((i+1)*x for i,x in enumerate(out))

